codeSnippet.code:
# High School Student Evaluation System
score = 88.5

if score >= 85:
    grade = 'Excellent (امتياز) 🌟'
elif score >= 75:
    grade = 'Very Good (جيد جداً) 👍'
elif score >= 65:
    grade = 'Good (جيد)'
elif score >= 50:
    grade = 'Pass (مقبول)'
else:
    grade = 'Fail (راسب) - Needs Summer Retake'

print(f'Evaluation: {grade}')

